    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([2, 1]), fmt([1, 2, 3, 4]), fmt([4, 3, 2, 1]), fmt([7, 7, 7]), fmt([-10**9, 10**9, 0]),
             fmt([2, 2, -1, 2]), fmt([9, 3, 7, 1, 4])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(min(n, 12))]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(2000)]))
    tests.append(fmt(list(range(2000, 0, -1))))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(2000)]))
    tests.append(fmt(sorted(rng.randint(-10**9, 10**9) for _ in range(2000))))
    return tests

